<div class="table-responsive"><table class="table"><thead><tr><th>Descrição literal</th><th>Quantidade</th><th>Preço unitário</th><th>Tributos</th></tr></thead><tbody><?php foreach($preview['items'] as $item){ ?><tr><td><?= $esc($item['description']); ?><?php if(($item['long_description']??'')!==''){ ?><pre style="white-space:pre-wrap"><?= $esc($item['long_description']); ?></pre><?php }if(($item['is_optional']??0)===1){ ?><p><?= ($item['is_selected']??1)===1?'Opcional escolhido — incluído nos valores':'Opcional não escolhido — fora do total e do PDF'; ?></p><?php } ?></td><td><?= $esc($item['qty'].' '.($item['unit']??'')); ?></td><td><?= $esc($item['rate']); ?></td><td><?php foreach($item['taxes'] as $tax){ ?><div><?= $esc($tax['name'].' '.$tax['rate'].'%'); ?></div><?php } ?></td></tr><?php } ?></tbody></table></div>
<p id="invoice-copy-amounts">Subtotal <?= $esc($preview['subtotal']); ?> · Tributos <?= $esc($preview['tax']); ?> · Desconto <?= $esc($preview['discount_total']); ?> · Ajuste <?= $esc($preview['options']['adjustment']); ?> · <strong>Total <?= $esc($preview['currency'].' '.$preview['total']); ?></strong></p><p>Desconto <?= $preview['options']['discount_mode']==='percent'?'percentual':'fixo'; ?>: <?= $esc($preview['options']['discount_value']); ?><?= $preview['options']['discount_mode']==='percent'?'%':''; ?> · <?= $preview['options']['discount_type']==='before_tax'?'Antes dos tributos':'Após os tributos'; ?>. Os itens e os valores desta revisão são lidos da origem persistida.</p>
